VALUES ('neetug-bio-520555', 520555, 'NEET-UG', 'Biology', 'plant-respiration', 'plant-respiration', 'NCERT Biology Class 11, Chapter 12', 'In the following reactions, which step of the citric acid cycle and oxidative phosphorylation produces the most ATP?', 'Fumarate → Malate', 'Succinate → Fumarate', 'α-Ketoglutarate → Succinate', 'Isocitrate → α-Ketoglutarate', 'C', 'The step of the citric acid cycle where the most ATP is produced through oxidative phosphorylation is from α-ketoglutarate to succinate. This reaction involves the reduction of FAD and NAD+, which are later used in the electron transport chain to generate ATP.', 100, 90, 'approved', true)
ON CONFLICT (source_id) DO UPDATE SET stem = EXCLUDED.stem, explanation = EXCLUDED.explanation, updated_at = now();

